'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const base='releases/v407',root='releases/v411',runtime='lts-v411-rsu-policy.js';
const read=(dir,name)=>fs.readFileSync(dir+'/'+name,'utf8'),hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const manifest=JSON.parse(read(root,'manifest.json')),provenance=JSON.parse(read(root,'provenance.json'));
assert.equal(manifest.release,'v411');assert.equal(manifest.base_release,'v407');assert.equal(manifest.entry,'app.html');
assert.deepEqual([...Object.keys(manifest.files),'manifest.json'].sort(),fs.readdirSync(root).sort());
assert.deepEqual(Object.keys(provenance.protected_base_files).sort(),fs.readdirSync(base).sort());
for(const[name,expected]of Object.entries(manifest.files))assert.equal(hash(root+'/'+name),expected,'release '+name);
for(const[name,expected]of Object.entries(provenance.protected_base_files))assert.equal(hash(base+'/'+name),expected,'immutable V407 '+name);
assert.equal(manifest.protected_manifest.path,base+'/manifest.json');assert.equal(hash(manifest.protected_manifest.path),manifest.protected_manifest.sha256);
assert.deepEqual(fs.readdirSync(root).sort(),[...fs.readdirSync(base),runtime].sort(),'one additive runtime');
for(const name of fs.readdirSync(base))if(!['app.html','manifest.json','provenance.json'].includes(name))assert.equal(hash(root+'/'+name),hash(base+'/'+name),'preserved existing runtime '+name);
let expected=read(base,'app.html').replaceAll('V407','V411').replace('v407-wealth-documents-20261104','v411-rsu-policy-20261104');
expected=expected.replace('</body>','<script src="'+runtime+'"></script>\n</body>');
assert.equal(read(root,'app.html'),expected);assert.equal(hash(root+'/'+runtime),hash(runtime));
assert.deepEqual(JSON.parse(read('mobile','current.json')),{release:process.env.LTS_MOBILE_RELEASE||'v411',entry:'../releases/'+(process.env.LTS_MOBILE_RELEASE||'v411')+'/app.html'});
for(const key of['financial_event_writers_added','received_financial_payloads_modified','client_reapplies_net_factor','conditional_scenario_creates_dates','private_http_validated','physical_mobile_validated'])assert.equal(provenance[key],false,key);
for(const key of['values_calculated_server_side','existing_quote_writers_preserved','grant_2026_calendar_preserved'])assert.equal(provenance[key],true,key);
console.log(JSON.stringify({pass:true,release:'v411',assets:fs.readdirSync(root).length,immutable_v407:true,client_reapplies_net_factor:false,financial_event_writers_added:false}));
